which expands to:
```Rust
pub fn migrate(
    deps: DepsMut,
    _env: Env,
    msg: MigrateMsg,
) -> Result<Response, axelar_wasm_std::error::ContractError> {
    let pkg_name = "router";
    let pkg_version = "1.2.0";
    let contract_version = cw2::get_contract_version(deps.storage)?;
    match (&contract_version.contract, &pkg_name) {
        (left_val, right_val) => {
            if !(*left_val == *right_val) {
                let kind = ::core::panicking::AssertKind::Eq;
                ::core::panicking::assert_failed(
                    kind,
                    &*left_val,
                    &*right_val,
                    ::core::option::Option::Some(
                        format_args!(
                            "cannot migrate from {0} contract to {1} contract",
                            contract_version.contract,
                            pkg_name,
                        ),
                    ),
                );
            }
        }
    };
    let old_version = semver::Version::parse(&contract_version.version)?;
    let version_requirement = semver::VersionReq::parse("~1.1.0")?;
    if !version_requirement.matches(&old_version) {
        {
            ::core::panicking::panic_fmt(
                format_args!(
                    "base version {0} does not match {1} version requirement",
                    old_version,
                    "~1.1.0",
                ),
            );
        }
    }
    cw2::set_contract_version(deps.storage, pkg_name, pkg_version)?;
    {
        v1_1_1::migrate(deps.storage, msg.chains_to_remove)?;
        Ok(Response::default())
    }
}
```


